// Public URL checks (GET, 15 s timeout, redirects followed, no-cache).
// marker = text that must appear in the response body. severity: crit = shop broken, warn = side service.
const CHECKS = [
  { key: 'home',       label: 'Strona główna',          url: 'https://lunae.pl/',                                            marker: 'wp-content/themes/lunae/',  severity: 'crit' },
  { key: 'product',    label: 'Strona produktu',        url: 'https://lunae.pl/produkt/figi-myosotis-alba/',                 marker: 'product_title',             severity: 'crit' },
  { key: 'store_api',  label: 'Store API (produkty)',   url: 'https://lunae.pl/wp-json/wc/store/v1/products?per_page=1',     marker: '[{"id":',                   severity: 'crit' },
  { key: 'cart',       label: 'Koszyk',                 url: 'https://lunae.pl/koszyk/',                                     marker: 'wp-block-woocommerce-cart', severity: 'crit' },
  { key: 'checkout',   label: 'Zamówienie (checkout)',  url: 'https://lunae.pl/zamowienie/',                                 marker: 'wp-block-woocommerce-c',    severity: 'crit' },
  { key: 'newsletter', label: 'Newsletter (listmonk)',  url: 'https://newsletter.lunae.pl/health',                           marker: '"data":true',               severity: 'warn' },
];
return CHECKS.map(c => ({ json: Object.assign({ expect_status: 200 }, c) }));

// ===== Progi / ustawienia (thresholds) =====
const SLOW_MS = 5000;                 // HTTP response slower than this = "wolno"
const HOST_STALE_MIN = 15;            // host.json older than this = stale
const DISK_WARN_PCT = 85;             // disk used % -> warning
const DISK_CRIT_PCT = 95;             // disk used % -> critical
const MEM_MIN_AVAILABLE_MB = 300;     // available RAM below this -> warning
const BACKUP_MAX_AGE_H = 30;          // lunae / n8n backup older than this -> warning
const STALE_CLI_MAX = 10;             // leftover wp-cli containers >= this -> low
const WOO_FAILED_24H_MAX = 2;         // failed orders in last 24 h >= this -> warning
const HTTP_CONFIRM_RUNS = 2;          // consecutive failing runs before an HTTP alert (~10 min)
const REMIND_H = { crit: 6, warn: 6, low: 24 };   // reminder interval for ongoing problems
const EXPECTED_CONTAINERS = {         // name -> severity when not running / unhealthy / missing
  'lunae-wordpress-1': 'crit',
  'lunae-db-1': 'crit',
  'lunae-listmonk-1': 'warn',
  'lunae-listmonk-db-1': 'warn',
  'n8n-n8n-1': 'warn',
  'minecraft-fabric': 'warn',
};
const WPCRON_TIMER = 'lunae-wpcron.timer';
const TZ = 'Europe/Warsaw';
// ============================================

const nowMs = Date.now();
const nowIso = new Date(nowMs).toISOString();
const SEV_RANK = { low: 1, warn: 2, crit: 3 };

// ---------- helpers ----------
const bad = new Map();        // key -> { sev, title, detail, confirm }
const okKeys = new Set();
const unknownKeys = new Set();
const families = [];          // key prefixes fully evaluated this run
const events = [];            // one-off notifications (e.g. container restart)
const metaUpserts = [];

function problem(key, sev, title, detail, confirm) {
  bad.set(key, { sev, title, detail: String(detail || '').slice(0, 300), confirm: confirm || 1 });
}
function ok(key) { okKeys.add(key); }
function unknown(key) { unknownKeys.add(key); }
function num(v) { return typeof v === 'number' && isFinite(v) ? v : null; }
function fmtNum(n, d) { return Number(n).toLocaleString('pl-PL', { maximumFractionDigits: d === undefined ? 1 : d }); }
function plOrders(n) { const t = n % 100, u = n % 10; return n === 1 ? 'zamówienie' : (u >= 2 && u <= 4 && (t < 12 || t > 14)) ? 'zamówienia' : 'zamówień'; }
function fmtSec(ms) { return fmtNum(ms / 1000, 1) + ' s'; }
function fmtDur(ms) {
  const m = Math.max(0, Math.round(ms / 60000));
  if (m < 60) return m + ' min';
  const h = Math.floor(m / 60), mm = m % 60;
  if (h < 48) return h + ' h' + (mm ? ' ' + mm + ' min' : '');
  const d = Math.floor(h / 24), hh = h % 24;
  return d + ' d' + (hh ? ' ' + hh + ' h' : '');
}
function safeFirst(nodeName) {
  try { const it = $(nodeName).first(); return it ? it.json : null; } catch (e) { return null; }
}

// ---------- previous state ----------
const rows = $input.all().map(i => i.json).filter(r => r && r.check_key);
const state = {};
for (const r of rows) state[r.check_key] = r;

// ---------- 1. HTTP checks ----------
const httpResults = (safeFirst('Collect HTTP results') || {}).results || [];
for (const r of httpResults) {
  const key = 'http:' + r.key;
  const slowKey = 'slow:' + r.key;
  const status = Number(r.status_code) || 0;
  let reason = '';
  if (r.error) reason = 'brak odpowiedzi (' + String(r.error).slice(0, 120) + ')';
  else if (status !== Number(r.expect_status || 200)) reason = 'HTTP ' + status;
  else if (!r.marker_ok) reason = 'HTTP ' + status + ', ale brak oczekiwanej treści';
  if (reason) {
    problem(key, r.severity || 'crit', r.label, reason + (r.error ? '' : ' (' + fmtSec(r.ms) + ')'), HTTP_CONFIRM_RUNS);
    unknown(slowKey);
  } else {
    ok(key);
    if (Number(r.ms) > SLOW_MS) problem(slowKey, 'warn', r.label + ' wolno odpowiada', fmtSec(r.ms) + ' (próg ' + fmtSec(SLOW_MS) + ')', HTTP_CONFIRM_RUNS);
    else ok(slowKey);
  }
}

// ---------- 2. host.json ----------
const parsed = safeFirst('Parse host.json') || {};
const readOut = safeFirst('Read host.json') || {};
let host = parsed && parsed.data && typeof parsed.data === 'object' ? parsed.data : null;
if (host && !host.generated_at) host = null;
if (!host) {
  const err = (parsed.error && (parsed.error.message || parsed.error)) || (readOut.error && (readOut.error.message || readOut.error)) || 'plik nie istnieje lub jest pusty';
  problem('hostfile:missing', 'warn', 'Status serwera (host.json)', 'nie można odczytać: ' + String(err).slice(0, 150), 2);
  unknown('hostfile:stale');
} else {
  ok('hostfile:missing');
  const genMs = Date.parse(host.generated_at);
  const ageMin = isNaN(genMs) ? Infinity : (nowMs - genMs) / 60000;
  if (ageMin > HOST_STALE_MIN) {
    problem('hostfile:stale', 'warn', 'Status serwera nieaktualny', 'host.json sprzed ' + (isFinite(ageMin) ? fmtDur(ageMin * 60000) : '?') + ' — czy działa n8n-host-status.timer?');
  } else {
    ok('hostfile:stale');

    // disk
    const used = num(host.disk && host.disk.used_pct);
    if (used === null) unknown('host:disk');
    else if (used >= DISK_CRIT_PCT) problem('host:disk', 'crit', 'Dysk ' + (host.disk.mount || '/'), fmtNum(used, 0) + '% zajęte (wolne ' + fmtNum(num(host.disk.free_gb) || 0) + ' GB)');
    else if (used >= DISK_WARN_PCT) problem('host:disk', 'warn', 'Dysk ' + (host.disk.mount || '/'), fmtNum(used, 0) + '% zajęte (wolne ' + fmtNum(num(host.disk.free_gb) || 0) + ' GB)');
    else ok('host:disk');

    // memory
    const avail = num(host.memory && host.memory.available_mb);
    if (avail === null) unknown('host:memory');
    else if (avail < MEM_MIN_AVAILABLE_MB) problem('host:memory', 'warn', 'Mało pamięci RAM', 'dostępne ' + fmtNum(avail, 0) + ' MB z ' + fmtNum(num(host.memory.total_mb) || 0, 0) + ' MB');
    else ok('host:memory');

    // containers
    const containers = Array.isArray(host.containers) ? host.containers : null;
    const missing = Array.isArray(host.expected_containers_missing) ? host.expected_containers_missing : null;
    if (containers && (containers.length || (missing && missing.length))) {
      families.push('host:container:');
      for (const name of Object.keys(EXPECTED_CONTAINERS)) {
        const key = 'host:container:' + name;
        const sev = EXPECTED_CONTAINERS[name];
        const c = containers.find(x => x && x.name === name);
        if ((missing && missing.includes(name)) || !c) problem(key, sev, 'Kontener ' + name, 'nie istnieje');
        else if (c.state === null || c.state === undefined) unknown(key);
        else if (c.state !== 'running') problem(key, sev, 'Kontener ' + name, 'stan: ' + c.state);
        else if (c.health === 'unhealthy') problem(key, sev, 'Kontener ' + name, 'healthcheck: unhealthy');
        else ok(key);
      }
      for (const c of containers) {
        if (!c || !c.name) continue;
        const rc = num(c.restart_count);
        if (rc === null) continue;
        const mkey = 'meta:restart:' + c.name;
        const prev = state[mkey] ? num(Number(state[mkey].value)) : null;
        if (prev !== null && rc > prev) {
          events.push({ sev: 'warn', title: 'Kontener ' + c.name + ' zrestartował się', detail: 'restart_count ' + prev + ' → ' + rc });
        }
        if (prev === null || rc !== prev) {
          metaUpserts.push({ check_key: mkey, status: 'meta', severity: '', since: nowIso, last_notified: '', fail_count: 0, detail: '', value: rc });
        }
      }
    }

    // failed systemd units
    if (Array.isArray(host.failed_units)) {
      families.push('host:unit:');
      for (const u of host.failed_units) {
        const name = typeof u === 'string' ? u : (u && (u.unit || u.name));
        if (name) problem('host:unit:' + name, 'warn', 'Usługa systemd ' + name, 'stan: failed');
      }
    }

    // backups
    const b = host.backups || {};
    const lunaeAge = num(b.lunae_last_success_age_h) !== null ? num(b.lunae_last_success_age_h) : num(b.lunae_newest_db_dump_age_h);
    if (lunaeAge === null) unknown('host:backup_lunae');
    else if (lunaeAge > BACKUP_MAX_AGE_H) problem('host:backup_lunae', 'warn', 'Kopia zapasowa sklepu', 'ostatnia udana ' + fmtNum(lunaeAge, 0) + ' h temu (próg ' + BACKUP_MAX_AGE_H + ' h)');
    else ok('host:backup_lunae');
    const n8nAge = num(b.n8n_newest_age_h);
    if (n8nAge === null) unknown('host:backup_n8n');
    else if (n8nAge > BACKUP_MAX_AGE_H) problem('host:backup_n8n', 'warn', 'Kopia zapasowa n8n', 'najnowsza ' + fmtNum(n8nAge, 0) + ' h temu (próg ' + BACKUP_MAX_AGE_H + ' h)');
    else ok('host:backup_n8n');

    // wp-cron timer
    const timers = Array.isArray(host.timers) ? host.timers : [];
    const t = timers.find(x => x && x.unit === WPCRON_TIMER);
    if (!t || t.active === null || t.active === undefined) unknown('host:wpcron_timer');
    else if (t.active !== 'active') problem('host:wpcron_timer', 'warn', 'WP-Cron (' + WPCRON_TIMER + ')', 'timer nieaktywny (' + t.active + ') — zadania WooCommerce nie ruszą');
    else ok('host:wpcron_timer');

    // low priority
    if (host.reboot_required === true) problem('host:reboot', 'low', 'Serwer wymaga restartu', 'po aktualizacjach (reboot-required)');
    else if (host.reboot_required === false) ok('host:reboot');
    else unknown('host:reboot');

    const cli = num(host.stale_cli_containers);
    if (cli === null) unknown('host:stale_cli');
    else if (cli >= STALE_CLI_MAX) problem('host:stale_cli', 'low', 'Stare kontenery wp-cli', cli + ' szt. (docker container prune?)');
    else ok('host:stale_cli');

    if (Array.isArray(host.errors) && host.errors.length) problem('host:probe_errors', 'low', 'host-status.sh: błędy sond', host.errors.slice(0, 3).join('; '));
    else if (Array.isArray(host.errors)) ok('host:probe_errors');
  }
}

// ---------- 3. WooCommerce failed orders ----------
const woo = safeFirst('Woo failed orders (24 h)') || {};
const AUTH_RE = /401|403|unauthori[sz]ed|forbidden|credential|consumer|woocommerce_rest_cannot|authenticat/i;
if (woo.error) {
  const msg = String(woo.error.message || woo.error.description || JSON.stringify(woo.error)).slice(0, 200);
  if (AUTH_RE.test(msg) || [401, 403].includes(Number(woo.error.httpCode))) {
    problem('woo:auth', 'low', 'WooCommerce API: brak dostępu', 'dane logowania nieuzupełnione lub błędne (' + msg.slice(0, 80) + ')');
    unknown('woo:api');
  } else {
    problem('woo:api', 'warn', 'WooCommerce API', 'błąd: ' + msg, HTTP_CONFIRM_RUNS);
    ok('woo:auth');
  }
  unknown('woo:failed_orders');
} else {
  const sc = Number(woo.statusCode) || 0;
  if (sc === 401 || sc === 403) {
    problem('woo:auth', 'low', 'WooCommerce API: brak dostępu', 'HTTP ' + sc + ' — uzupełnij klucze API w n8n (WooCommerce · lunae.pl)');
    ok('woo:api'); unknown('woo:failed_orders');
  } else if (sc !== 200) {
    problem('woo:api', 'warn', 'WooCommerce API', 'HTTP ' + (sc || '?'), HTTP_CONFIRM_RUNS);
    ok('woo:auth'); unknown('woo:failed_orders');
  } else {
    ok('woo:auth'); ok('woo:api');
    let body = woo.body;
    if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = null; } }
    if (!Array.isArray(body)) {
      problem('woo:api', 'warn', 'WooCommerce API', 'nieoczekiwana odpowiedź (nie lista zamówień)', HTTP_CONFIRM_RUNS);
      unknown('woo:failed_orders');
    } else if (body.length >= WOO_FAILED_24H_MAX) {
      const nums = body.slice(0, 8).map(o => '#' + (o.number || o.id) + (o.payment_method_title ? ' (' + o.payment_method_title + ')' : '')).join(', ');
      problem('woo:failed_orders', 'warn', 'Nieudane płatności', body.length + (body.length >= 50 ? '+' : '') + ' ' + plOrders(body.length) + ' ze statusem „nieudane” w 24 h: ' + nums + ' — sprawdź Przelewy24');
    } else ok('woo:failed_orders');
  }
}

// ---------- 4. state transitions ----------
const newItems = [], reminders = [], recoveries = [], upserts = [];

for (const [key, p] of bad) {
  const prev = state[key];
  const was = prev && prev.status === 'problem';
  const failCount = was ? (Number(prev.fail_count) || 0) + 1 : 1;
  const since = was && prev.since ? prev.since : nowIso;
  let lastNotified = was && prev.last_notified ? prev.last_notified : '';
  if (failCount >= p.confirm) {
    if (!lastNotified) {
      newItems.push(p); lastNotified = nowIso;
    } else if ((SEV_RANK[p.sev] || 0) > (SEV_RANK[prev.severity] || 0)) {
      newItems.push(Object.assign({}, p, { escalated: true })); lastNotified = nowIso;
    } else {
      const lastMs = Date.parse(lastNotified);
      if (isNaN(lastMs) || nowMs - lastMs >= (REMIND_H[p.sev] || 6) * 3600000) {
        reminders.push(Object.assign({}, p, { since })); lastNotified = nowIso;
      }
    }
  }
  upserts.push({ check_key: key, status: 'problem', severity: p.sev, since, last_notified: lastNotified, fail_count: failCount, detail: (p.title + ' — ' + p.detail).slice(0, 400), value: prev && prev.value !== undefined ? prev.value : null });
}

for (const key of Object.keys(state)) {
  const prev = state[key];
  if (prev.status !== 'problem' || bad.has(key) || unknownKeys.has(key)) continue;
  const evaluated = okKeys.has(key) || families.some(f => key.startsWith(f));
  if (!evaluated) continue;
  if (prev.last_notified) {
    const title = String(prev.detail || key).split(' — ')[0];
    const sinceMs = Date.parse(prev.since);
    recoveries.push({ title, dur: isNaN(sinceMs) ? '' : fmtDur(nowMs - sinceMs) });
  }
  upserts.push({ check_key: key, status: 'ok', severity: '', since: nowIso, last_notified: '', fail_count: 0, detail: '', value: prev.value !== undefined ? prev.value : null });
}
for (const m of metaUpserts) upserts.push(m);
for (const e of events) newItems.push(e);

// ---------- 5. message ----------
const lines = [];
const stamp = DateTime.fromMillis(nowMs).setZone(TZ).toFormat('dd.LL HH:mm');
const lowTag = p => p.sev === 'low' ? ' _(niski priorytet)_' : '';
if (newItems.length || reminders.length || recoveries.length) lines.push('**lunae · monitoring** — ' + stamp);
if (newItems.length) {
  const hasCrit = newItems.some(p => p.sev === 'crit');
  lines.push((hasCrit ? '🔴' : '🟡') + ' **Nowe problemy**');
  for (const p of newItems) lines.push('• **' + p.title + '**: ' + p.detail + (p.escalated ? ' _(pogorszenie)_' : '') + lowTag(p));
}
if (reminders.length) {
  const hasCrit = reminders.some(p => p.sev === 'crit');
  lines.push((hasCrit ? '🔴' : '🟡') + ' **Nadal trwa**');
  for (const p of reminders) {
    const sMs = Date.parse(p.since);
    lines.push('• **' + p.title + '**: ' + p.detail + (isNaN(sMs) ? '' : ' — od ' + fmtDur(nowMs - sMs)) + lowTag(p));
  }
}
if (recoveries.length) {
  lines.push('🟢 **Naprawione**');
  for (const r of recoveries) lines.push('• ' + r.title + (r.dur ? ' — po ' + r.dur : ''));
}
let content = lines.join('\n');
if (content.length > 1990) content = content.slice(0, 1985) + '\n…';

return [{ json: {
  has_message: content.length > 0,
  content,
  upserts,
  summary: {
    checked_at: nowIso,
    problems: [...bad.keys()],
    new: newItems.length, reminders: reminders.length, recovered: recoveries.length,
    http_ms: Object.fromEntries(httpResults.map(r => [r.key, r.ms])),
  },
} }];
